const seed=rawSeed as any;
const defaultSeason=SEASONS[0];
const EMPTY:Notebook={observations:{},watchedGames:{}};
const cn=(...s:(string|false|undefined)[])=>s.filter(Boolean).join(' ');
const dateLabel=(s:string)=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date(s+'T04:00:00Z'));
const clock=(s:string)=>s?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(s)):'时间待定';
const requests=new Map<string,Promise<Envelope>>();
function getSeed(resource:string,season:string,id=''):Envelope{return (resource==='boxscore'?seed.boxes[id]:['players','teams','standings','bpm'].includes(resource)?seed.seasons[season]?.[resource]:seed[resource])||{rows:[],stale:true};}
function useDataset(resource:string,season=defaultSeason,id='',interval=120000){
 const key=`${resource}:${season}:${id}`;const [result,setResult]=useState<{key:string;data:Envelope}>(()=>({key,data:getSeed(resource,season,id)}));const [loading,setLoading]=useState(false);const mounted=useRef(true);const latest=useRef(key);latest.current=key;
 const reload=useCallback(async()=>{setLoading(true);let task=requests.get(key);if(!task){task=fetchDataset(resource,season,id).finally(()=>requests.delete(key));requests.set(key,task);}try{const data=await task;if(mounted.current&&latest.current===key)setResult(prev=>({key,data:retainLatestDataset(prev.key===key?prev.data:getSeed(resource,season,id),data)}));}catch{if(mounted.current&&latest.current===key)setResult(prev=>({key,data:{...(prev.key===key?prev.data:getSeed(resource,season,id)),stale:true,warning:'网络暂不可用，已保留最近一次数据。'}}));}finally{if(mounted.current&&latest.current===key)setLoading(false);}},[key,resource,season,id]);
 useEffect(()=>{mounted.current=true;reload();const resume=()=>{if(document.visibilityState==='visible')reload()};const timer=setInterval(resume,interval);window.addEventListener('focus',resume);window.addEventListener('online',resume);document.addEventListener('visibilitychange',resume);return()=>{mounted.current=false;clearInterval(timer);window.removeEventListener('focus',resume);window.removeEventListener('online',resume);document.removeEventListener('visibilitychange',resume)}},[reload,interval]);
 return {data:result.key===key?result.data:getSeed(resource,season,id),loading,reload};
}
function TeamLogo({id,className=''}:{id:number;className?:string}){return <img className={cn('team-logo',className)} src={logo(id)} alt={TEAMS[id]?.name||'球队'} loading="lazy" onError={e=>{e.currentTarget.style.opacity='.12'}}/>}
const LEGACY_CODES=new Set(['SEA','NJN','VAN','NOH','NOK','CHH','WSB','SDC','KCK']);
function StatTeamLogo({row,className=''}:{row:StatRow;className?:string}){const code=row.TEAM_ABBREVIATION||row.TeamAbbreviation;return LEGACY_CODES.has(code)?<span className={cn('team-logo','legacy-team-logo',className)} title={row.TEAM_NAME||[row.TeamCity,row.TeamName].filter(Boolean).join(' ')}>{code}</span>:<TeamLogo id={row.TEAM_ID||row.TeamID} className={className}/>}
function Portrait({id,name,className=''}:{id:number;name:string;className?:string}){return <img className={cn('portrait',className)} src={headshot(id)} alt={name} loading="lazy" onError={e=>{e.currentTarget.style.opacity='0'}}/>}
function Source({data,loading,onRefresh}:{data:Envelope;loading?:boolean;onRefresh?:()=>void}){return <div className="source-line"><span className={cn('source-dot',data.stale&&'stale')}/><span>{data.source||'NBA.com'}{data.updatedAt?' · '+new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(data.updatedAt)):''}{data.stale?' · '+((data.rows?.length||data.games?.length||data.game)?'缓存数据':'暂不可用'):''}</span>{data.url&&<a href={data.url} target="_blank" rel="noreferrer" aria-label="打开数据来源"><ExternalLink size={12}/></a>}{onRefresh&&<button className="icon-button tiny" onClick={onRefresh} aria-label="刷新数据"><RefreshCw size={12} className={loading?'spinning':''}/></button>}</div>}
function SeasonSelect({value,onChange}:{value:string;onChange:(s:string)=>void}){return <label className="season-select"><span className="sr-only">赛季</span><select value={value} onChange={e=>onChange(e.target.value)}>{SEASONS.map(s=><option key={s} value={s}>{s}</option>)}</select><ChevronDown size={14}/><span>常规赛</span></label>}
function EmptyState({title,children,icon}:{title:string;children?:React.ReactNode;icon?:React.ReactNode}){return <div className="empty-state">{icon||<CalendarDays size={35} strokeWidth={1}/>}<h3>{title}</h3>{children}</div>}
function App(){
 const predictions=usePredictions();const notebookStorageKey=predictions.user?STORAGE_KEY+':'+predictions.user.id:STORAGE_KEY;const [loadedNotebookKey,setLoadedNotebookKey]=useState('');const [playerId,setPlayerId]=useState<number|null>(null);const [playerSeason,setPlayerSeason]=useState<string|undefined>(undefined);const [playerSection,setPlayerSection]=useState('active');
 const [view,setView]=useState('home');const [gameId,setGameId]=useState<string|null>(null);const [notebook,setNotebook]=useState<Notebook>(EMPTY);const [ready,setReady]=useState(false);const [storageStatus,setStorageStatus]=useState('');const [showNotebook,setShowNotebook]=useState(false);const [toast,setToast]=useState('');const [saved,setSaved]=useState(false);
 const schedule=useDataset('schedule',defaultSeason,'',120000);const scoreboard=useDataset('scoreboard',defaultSeason,'',15000);
 const games=useMemo(()=>mergeGameFeeds(schedule.data,scoreboard.data),[schedule.data,scoreboard.data]);
 useEffect(()=>{const read=()=>{const h=window.location.hash.slice(1).split('/');const v=['home','games','picks','statistics','contrast','players'].includes(h[0])?h[0]:'home';setView(v);setGameId(['games','picks'].includes(v)&&/^00\d{8}$/.test(h[1]||'')?h[1]:null);setPlayerId(v==='players'&&/^[1-9]\d{1,8}$/.test(h[1]||'')?Number(h[1]):null);setPlayerSeason(v==='players'&&SEASONS.includes(h[2])?h[2]:undefined);if(v==='players'&&['active','history','moments','challenge'].includes(h[1]))setPlayerSection(h[1]);};read();window.addEventListener('hashchange',read);return()=>window.removeEventListener('hashchange',read)},[]);
 useEffect(()=>{if(predictions.authLoading)return;setReady(false);setNotebook(EMPTY);try{const raw=localStorage.getItem(notebookStorageKey);setNotebook(raw?parseNotebook(JSON.parse(raw)):EMPTY);setStorageStatus('')}catch{setStorageStatus('无法读取本地手记，请检查浏览器存储权限。')}setLoadedNotebookKey(notebookStorageKey);setReady(true)},[notebookStorageKey,predictions.authLoading]);
 useEffect(()=>{if(!ready||loadedNotebookKey!==notebookStorageKey||predictions.authLoading)return;setSaved(false);const timer=setTimeout(()=>{try{localStorage.setItem(notebookStorageKey,JSON.stringify(exportNotebook(notebook)));setSaved(true);setStorageStatus('')}catch{setStorageStatus('自动保存失败，请立即导出手记备份。')}},400);return()=>clearTimeout(timer)},[notebook,ready,notebookStorageKey,loadedNotebookKey,predictions.authLoading]);
 useEffect(()=>{if(!ready||loadedNotebookKey!==notebookStorageKey||predictions.authLoading)return;const flush=()=>{try{localStorage.setItem(notebookStorageKey,JSON.stringify(exportNotebook(notebook)))}catch{}};window.addEventListener('pagehide',flush);return()=>{flush();window.removeEventListener('pagehide',flush)}},[notebook,ready,notebookStorageKey,loadedNotebookKey,predictions.authLoading]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(t)},[toast]);
 const navigate=(v:string,id?:string)=>{window.location.hash=v+(id?'/'+id:'');setView(v);setGameId(['games','picks'].includes(v)?id||null:null);if(v==='players'){setPlayerId(null);setPlayerSeason(undefined);setPlayerSection(id&&['active','history','moments','challenge'].includes(id)?id:'active')}};
 const openPlayer=(id:number,season?:string)=>{window.location.hash='players/'+id+(season?'/'+season:'');setView('players');setGameId(null);setPlayerId(id);setPlayerSeason(season)};
 const updateNote=(n:Observation)=>setNotebook(prev=>{const observations={...prev.observations};const key=noteKey(n.gameId,n.playerId);if(hasObservation(n))observations[key]=n;else delete observations[key];return {...prev,observations}});
 const toggleWatch=(id:string)=>setNotebook(prev=>({...prev,watchedGames:{...prev.watchedGames,[id]:!prev.watchedGames[id]}}));
 const exportNotes=()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(exportNotebook(notebook),null,2)],{type:'application/json'}));a.href=url;a.download=`courtside-notebook-${beijingDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setToast('观赛手记已导出')};
 const importNotes=async(file:File)=>{try{if(file.size>5*1024*1024)throw Error('文件过大，请选择 5 MB 以内的手记。');const next=parseNotebook(JSON.parse(await file.text()));setNotebook(prev=>{const observations={...prev.observations};for(const [key,value] of Object.entries(next.observations))if(!observations[key]||new Date(value.updatedAt)>new Date(observations[key].updatedAt))observations[key]=value;return {observations,watchedGames:{...prev.watchedGames,...next.watchedGames}}});setToast(`已合并 ${Object.keys(next.observations).length} 条球员记录`)}catch(e){setToast(e instanceof Error?e.message:'文件导入失败')}};
 const currentGame=games.find(g=>g.gameId===gameId);
 const refreshPredictionGame=async(game:Game)=>{
  const results=await Promise.allSettled([fetchDataset('schedule',defaultSeason),fetchDataset('scoreboard',defaultSeason)]);
  const candidates=results.flatMap(result=>result.status==='fulfilled'?(result.value.games||[]).filter(g=>g.gameId===game.gameId):[]);
  if(!candidates.length)throw Error('无法核对开赛状态，请刷新比赛后重试');
  return candidates.reduce((latest,g)=>({...latest,...(g.gameStatus>=latest.gameStatus?g:{}),gameTimeUTC:(g.gameStatus>=latest.gameStatus&&g.gameTimeUTC)||latest.gameTimeUTC}),game);
 };
 const detail=gameId?(currentGame?<GameDetail key={gameId} game={currentGame} notebook={notebook} onUpdate={updateNote} onBack={()=>navigate(view)} onWatch={()=>toggleWatch(gameId)} saved={saved} ready={ready&&loadedNotebookKey===notebookStorageKey&&!predictions.authLoading} predictions={predictions} refreshGame={()=>refreshPredictionGame(currentGame)}/>:<div className="page"><button className="back-button" onClick={()=>navigate(view)}><ArrowLeft size={16}/>返回比赛列表</button><EmptyState title="这场比赛不在当前赛季赛程中"><p>已保存的观赛手记仍可在右上角打开。</p></EmptyState></div>):null;
 return <div className={cn('app-shell',view==='home'&&'home-shell',view==='players'&&'players-shell')}><header className={view==='home'?'home-masthead':'site-header'}><a className="brand" href="#home" aria-label="COURTSIDE 首页"><svg viewBox="0 0 36 36" fill="none" aria-hidden="true"><circle cx="18" cy="18" r="15" stroke="currentColor" strokeWidth="2"/><path d="M3 18h30M18 3v30M8 6q19 12 0 24M28 6Q9 18 28 30" stroke="currentColor" strokeWidth="1.8"/></svg><span>COURTSIDE<span className="brand-period">.</span></span></a><nav className="main-nav" aria-label="主导航">{[['home','Home'],['games','Game Center'],['picks','Picks'],['statistics','Statistics'],['contrast','Contrast'],['players','Players']].map(([v,label])=><a key={v} href={'#'+v} className={cn('nav-tab',view===v&&'active')} aria-current={view===v?'page':undefined}>{label}</a>)}</nav><div className="header-tools"><button className="notebook-button" onClick={()=>setShowNotebook(true)}><Bookmark size={16}/><span>我的观赛手记</span>{Object.keys(notebook.observations).length>0&&<b>{Object.values(notebook.observations).filter(hasObservation).length}</b>}</button><AccountButton store={predictions} compact/></div></header>
 <main className={view==='home'?'home-stage':'main-stage'}>{view==='home'?<Home onNavigate={navigate}/>:view==='games'?detail||<GameCenter games={games} onGame={id=>navigate('games',id)} notebook={notebook} data={scoreboard.data} loading={schedule.loading||scoreboard.loading} refresh={()=>{schedule.reload();scoreboard.reload()}}/>:view==='picks'?detail||<PredictionCenter games={games} data={scoreboard.data} loading={schedule.loading||scoreboard.loading} refresh={()=>{schedule.reload();scoreboard.reload()}} store={predictions} onGame={id=>navigate('picks',id)} refreshGame={refreshPredictionGame}/>:view==='statistics'?<Statistics onPlayer={openPlayer}/>:view==='players'?<PlayerCenter key={predictions.user?.id||'guest'} accountId={predictions.user?.id} playerId={playerId} initialSeason={playerSeason} section={playerSection} onOpen={openPlayer} onSection={section=>navigate('players',section)} onBack={()=>navigate('players',playerSection)}/>:<Contrast onToast={setToast} onPlayer={openPlayer}/>}</main>
 {storageStatus&&<div className="storage-warning" role="alert"><WifiOff size={15}/>{storageStatus}<button onClick={exportNotes}>导出备份</button></div>}
 {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/>{toast}</div>}
 {predictions.showConnect&&<AccountDialog store={predictions}/>}
 {showNotebook&&<NotebookDialog notebook={notebook} onClose={()=>setShowNotebook(false)} onOpen={id=>{setShowNotebook(false);navigate('games',id)}} onExport={exportNotes} onImport={importNotes} onDelete={key=>setNotebook(prev=>{const observations={...prev.observations};delete observations[key];return {...prev,observations}})}/>}
 </div>;
}
