function Home({onNavigate}:{onNavigate:(v:string,id?:string)=>void}){
 const [slide,setSlide]=useState(0);
 const touch=useRef<{x:number;y:number}|null>(null);const switcher=useRef<HTMLDivElement>(null);
 const change=useCallback((direction:number)=>setSlide(value=>(value+direction+slides.length)%slides.length),[]);
 useEffect(()=>{const key=(event:KeyboardEvent)=>{if(document.querySelector('dialog[open]')||event.altKey||event.metaKey||event.ctrlKey||/INPUT|TEXTAREA|SELECT/.test((event.target as HTMLElement)?.tagName))return;if(event.key==='ArrowRight'){event.preventDefault();change(1)}if(event.key==='ArrowLeft'){event.preventDefault();change(-1)}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[change]);
 useEffect(()=>{const element=switcher.current;const active=element?.children[slide] as HTMLElement|undefined;if(element&&active)element.scrollTo({left:Math.max(0,active.offsetLeft-element.offsetLeft-element.clientWidth/2+active.clientWidth/2),behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});const preload=new Image();preload.src=assetPath('images/'+slides[(slide+1)%slides.length].image)},[slide]);
 const s=slides[slide];
 return <section className="home-poster" data-slide={slide} data-copy={s.copy} aria-label="球员主题海报" onPointerDown={event=>{if(event.pointerType==='touch')touch.current={x:event.clientX,y:event.clientY}}} onPointerUp={event=>{if(!touch.current)return;const dx=event.clientX-touch.current.x;const dy=event.clientY-touch.current.y;touch.current=null;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)change(dx<0?1:-1)}} onPointerCancel={()=>{touch.current=null}}>
  <div className="hero-scene" key={s.image}>
   <img className="hero-photo" src={assetPath('images/'+s.image)} alt={s.player+' 比赛照片'} style={{'--hero-focus':s.focal,'--hero-mobile-focus':s.mobileFocal} as CSSProperties} fetchPriority="high"/>
   <div className="poster-shade"/>
   <svg className="hero-court-art" viewBox="0 0 800 600" fill="none" aria-hidden="true"><g className="court-markings"><path d="M800 95H695a205 205 0 0 0 0 410h105M800 222H650v156h150M730 222a78 78 0 0 0 0 156M776 272v56"/><circle cx="754" cy="300" r="14"/><path d="M746 300h16"/></g><path className="shot-trail" d="M110 515Q425 30 754 300" pathLength="1"/><g className="flying-basketball"><circle r="7.5"/><path d="M-7.5 0h15M0-7.5v15M-5-5Q5 0-5 5M5-5Q-5 0 5 5"/><animateMotion dur="1.3s" path="M110 515Q425 30 754 300" fill="freeze"/></g></svg>
   <div className="hero-copy"><h1><span className="hero-headline">{s.line1}</span><em>{s.line2}</em></h1><button className="primary-button hero-cta" onClick={()=>onNavigate('games')}><BasketballIcon/><span>进入比赛日</span><ArrowUpRight size={20}/></button></div>
   <div className="hero-player"><span className="player-number">{s.number}</span><div><strong>{s.player}</strong><span>{s.team}</span></div></div>
  </div>
  <button className="home-classics-link" onClick={()=>onNavigate('players','moments')}><Volume2 size={13}/><span>经典回放</span><ArrowUpRight size={14}/></button>
  <div className="poster-controls"><button className="poster-arrow" onClick={()=>change(-1)} aria-label="上一张球员海报"><ChevronLeft size={18}/></button><div ref={switcher} className="poster-switcher" aria-label="切换球员海报">{slides.map((x,i)=><button key={x.player} className={cn(slide===i&&'active')} onClick={()=>setSlide(i)} aria-label={x.player} aria-pressed={slide===i}><span>{x.number}</span><i><b/></i></button>)}</div><button className="poster-arrow" onClick={()=>change(1)} aria-label="下一张球员海报"><ChevronRight size={18}/></button></div>
 </section>;
}
function PageHeading({eyebrow,title,children}:{eyebrow:string;title:string;children?:React.ReactNode}){return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}<span>.</span></h1></div><div className="heading-actions">{children}</div></div>}
function GameCenter({games,onGame,notebook,data,loading,refresh}:{games:Game[];onGame:(id:string)=>void;notebook:Notebook;data:Envelope;loading:boolean;refresh:()=>void}){
 const [date,setDate]=useState(()=>beijingDate());const [team,setTeam]=useState('all');const [filter,setFilter]=useState('all');const today=beijingDate();const dates=Array.from({length:7},(_,i)=>shiftDate(date,i-3));const filtered=games.filter(g=>g.gameTimeUTC&&beijingDate(g.gameTimeUTC)===date&&(team==='all'||String(g.homeTeam.teamId)===team||String(g.awayTeam.teamId)===team)&&(filter!=='watched'||notebook.watchedGames[g.gameId]));const nextDay=games.map(g=>g.gameTimeUTC?beijingDate(g.gameTimeUTC):'').filter(d=>d>date).sort()[0];const prevDay=games.map(g=>g.gameTimeUTC?beijingDate(g.gameTimeUTC):'').filter(d=>d<date).sort().at(-1);
 return <section className="page games-page"><PageHeading eyebrow="GAME CENTER" title="GAME DAY"><div className="live-label"><i/>{data.stale?'比赛动态 · 缓存':'比赛动态 · 15 秒刷新'}</div><button className="outline-button" onClick={refresh}><RefreshCw size={14} className={loading?'spinning':''}/>刷新</button></PageHeading><div className="game-toolbar"><div className="date-title"><CalendarDays size={18}/><span>{dateLabel(date)}</span><label className="date-picker"><span className="sr-only">选择比赛日期（北京时间）</span><input type="date" value={date} onChange={e=>e.target.value&&setDate(e.target.value)}/><ChevronDown size={14}/></label></div><div className="toolbar-right"><span className="timezone">北京时间</span><button className="text-button" onClick={()=>setDate(today)}>今天</button><select className="filter-select" aria-label="筛选球队" value={team} onChange={e=>setTeam(e.target.value)}><option value="all">全部球队</option>{Object.entries(TEAMS).map(([id,t])=><option key={id} value={id}>{t.code} {t.name}</option>)}</select><button className={cn('filter-button',filter==='watched'&&'selected')} onClick={()=>setFilter(filter==='all'?'watched':'all')}><Bookmark size={14}/><span>已观看</span></button></div></div><div className="date-strip"><button className="icon-button" onClick={()=>setDate(shiftDate(date,-7))} aria-label="上一周"><ChevronLeft size={19}/></button>{dates.map(d=>{const count=games.filter(g=>g.gameTimeUTC&&beijingDate(g.gameTimeUTC)===d).length;return <button className={cn('date-chip',date===d&&'selected')} key={d} onClick={()=>setDate(d)}><span>{new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',weekday:'short'}).format(new Date(d+'T04:00:00Z'))}</span><strong>{d.slice(5).replace('-',' / ')}</strong><small>{count?count+' 场比赛':'休赛日'}</small></button>})}<button className="icon-button" onClick={()=>setDate(shiftDate(date,7))} aria-label="下一周"><ChevronRight size={19}/></button></div><div className="game-results scroll-area">{filtered.length?<div className="games-grid">{filtered.map((g,i)=>{const count=Object.values(notebook.observations).filter(n=>n.gameId===g.gameId&&hasObservation(n)).length;return <button key={g.gameId} className={cn('game-card',i===0&&'featured',g.gameStatus===2&&'live')} onClick={()=>onGame(g.gameId)} style={{'--home-color':TEAMS[g.homeTeam.teamId]?.color||'#ff6333','--away-color':TEAMS[g.awayTeam.teamId]?.color||'#367bc2'} as CSSProperties}><div className="game-card-top"><span className={cn('game-status',g.gameStatus===2&&'is-live')}>{g.gameStatus===2&&<i/>}{g.gameStatus===3?'FINAL':g.gameStatus===2?g.gameStatusText:clock(g.gameTimeUTC)}</span><span>{notebook.watchedGames[g.gameId]?<><CheckCheck size={13}/> 已观看</>:g.gameLabel==='Preseason'?'PRESEASON':'NBA'}</span></div><div className="matchup"><div><TeamLogo id={g.awayTeam.teamId}/><strong>{g.awayTeam.teamTricode}</strong><small>{TEAMS[g.awayTeam.teamId]?.name||g.awayTeam.teamName}</small></div><div className="score">{g.gameStatus===1?<span className="vs">VS</span>:<><b key={'away'+g.awayTeam.score} className="score-tick">{g.awayTeam.score}</b><span>:</span><b key={'home'+g.homeTeam.score} className="score-tick">{g.homeTeam.score}</b></>}</div><div><TeamLogo id={g.homeTeam.teamId}/><strong>{g.homeTeam.teamTricode}</strong><small>{TEAMS[g.homeTeam.teamId]?.name||g.homeTeam.teamName}</small></div></div><div className="game-card-bottom"><span>{count?<><BookOpen size={13}/>{count} 位球员的观赛记录</>:g.arenaName||'AWAY / HOME'}</span><span>进入比赛<ArrowUpRight size={17}/></span></div></button>})}</div>:<EmptyState title={filter==='watched'?'这一天还没有标记已观看的比赛':team!=='all'?'这支球队当天没有比赛':'今天，让篮球歇一会儿'}><p>{dateLabel(date)}{filter==='watched'?' · 取消筛选可查看全部比赛':' · 暂无符合条件的比赛'}</p><div className="empty-actions">{prevDay&&<button className="outline-button" onClick={()=>{setDate(prevDay);setTeam('all');setFilter('all')}}><ArrowLeft size={14}/>上一个比赛日</button>}{nextDay&&<button className="primary-button small" onClick={()=>{setDate(nextDay);setTeam('all');setFilter('all')}}>下一个比赛日<ArrowRight size={16}/></button>}</div></EmptyState>}</div><footer className="page-footer"><Source data={data}/></footer></section>
}
function Statistics({onPlayer}:{onPlayer:(id:number,season?:string)=>void}){
 const [season,setSeason]=useState(defaultSeason);const [tab,setTab]=useState('players');const [metric,setMetric]=useState('PTS');const [q,setQ]=useState('');const [minGP,setMinGP]=useState(1);const [conference,setConference]=useState('all');const [page,setPage]=useState(1);const [direction,setDirection]=useState(-1);const [advancedSource,setAdvancedSource]=useState('nba');const resource=tab==='standings'?'standings':tab==='teams'?'teams':tab==='advanced'&&advancedSource==='bpm'?'bpm':'players';const {data,loading,reload}=useDataset(resource,season);const rows=data.rows||[];
 const metrics=tab==='advanced'?(advancedSource==='bpm'?['BPM','OBPM','DBPM','VORP','PER','WS']:['TS_PCT','EFG_PCT','USG_PCT','OFF_RATING','DEF_RATING','NET_RATING','PACE','PIE']):tab==='teams'?['PTS','REB','AST','FG3_PCT','OFF_RATING','DEF_RATING','NET_RATING','PACE']:['PTS','REB','AST','STL','BLK','FG3M','FG3_PCT','FG_PCT','FT_PCT'];
 const chosenMetric=metrics.includes(metric)?metric:metrics[0];const bpm=resource==='bpm';const filtered=useMemo(()=>rows.filter(r=>(tab==='teams'||bpm||Number(r.GP)>=minGP)&&(!q||(r.PLAYER_NAME||r.TEAM_NAME||'').toLowerCase().includes(q.toLowerCase())||(TEAMS[r.TEAM_ID]?.name||'').includes(q))&&(conference==='all'||TEAMS[r.TEAM_ID]?.conference===conference)).filter(r=>Number.isFinite(Number(r[chosenMetric]))&&r[chosenMetric]!==null&&r[chosenMetric]!==undefined).sort((a,b)=>direction*(Number(a[chosenMetric])-Number(b[chosenMetric]))),[rows,tab,bpm,minGP,q,conference,chosenMetric,direction]);
 useEffect(()=>{setPage(1)},[tab,season,chosenMetric,q,minGP,conference,direction]);
 const changeTab=(value:string)=>{setTab(value);setMetric(value==='advanced'?'TS_PCT':'PTS');setDirection(-1)};
 const changeMetric=(m:string)=>{setMetric(m);setDirection(METRICS[m]?.lower?1:-1)};
 const columns=[...new Set([chosenMetric,...(tab==='advanced'?metrics:tab==='teams'?['PTS','REB','AST','FG_PCT','FG3_PCT','NET_RATING']:['PTS','REB','AST','STL','BLK','FG3_PCT'])])].slice(0,8);
 return <section className="page stats-page"><PageHeading eyebrow="STATISTICS" title="THE NUMBERS"><SeasonSelect value={season} onChange={s=>{setSeason(s);setMinGP(s===defaultSeason?1:20)}}/></PageHeading><div className="subnav" aria-label="统计分类">{[['standings','东西部排名'],['players','球员数据'],['teams','球队数据'],['advanced','高阶数据']].map(([id,label])=><button key={id} className={cn(tab===id&&'active')} onClick={()=>changeTab(id)}>{label}{tab===id&&<span/>}</button>)}<div className="subnav-end"><Source data={data} loading={loading} onRefresh={reload}/></div></div>{tab==='standings'?<Standings rows={rows} loading={loading} historical={Number(season.slice(0,4))<2024}/>:<><div className="stats-controls">{tab==='advanced'&&<div className="segmented compact"><button onClick={()=>{setAdvancedSource('nba');changeMetric('TS_PCT')}} className={cn(advancedSource==='nba'&&'active')}>NBA Advanced</button><button onClick={()=>{setAdvancedSource('bpm');changeMetric('BPM')}} className={cn(advancedSource==='bpm'&&'active')}>BPM / VORP</button></div>}<div className="metric-chips">{metrics.map(m=><button key={m} title={METRICS[m]?.description} className={cn(chosenMetric===m&&'selected')} onClick={()=>changeMetric(m)}>{METRICS[m]?.short}<small>{METRICS[m]?.label}</small></button>)}</div></div>{!bpm&&tab!=='teams'&&filtered.length>0&&page===1&&!q&&<div className="leader-podium">{filtered.slice(0,3).map((r,i)=><div className={cn('leader-card','leader-'+i)} key={r.PLAYER_ID} style={{'--team-color':TEAMS[r.TEAM_ID]?.color||'#f36b3b'} as CSSProperties}><span className="leader-rank">0{i+1}</span><div className="leader-info"><span className="leader-team"><StatTeamLogo row={r}/>{r.TEAM_ABBREVIATION}</span><h3><button className="player-text-link" onClick={()=>onPlayer(r.PLAYER_ID,season)}>{r.PLAYER_NAME}<ArrowUpRight size={12}/></button></h3><div className="leader-value">{formatStat(r[chosenMetric],chosenMetric)}<small>{METRICS[chosenMetric]?.short}</small></div></div><Portrait id={r.PLAYER_ID} name={r.PLAYER_NAME}/></div>)}</div>}<div className="table-toolbar"><label className="search-input"><Search size={15}/><input placeholder={tab==='teams'?'搜索球队':'搜索球员或球队'} aria-label="搜索统计数据" value={q} onChange={e=>setQ(e.target.value)}/>{q&&<button onClick={()=>setQ('')} aria-label="清空搜索"><X size={12}/></button>}</label><div className="toolbar-right"><select className="filter-select" aria-label="筛选分区" value={conference} onChange={e=>setConference(e.target.value)}><option value="all">全部分区</option><option value="East">东部</option><option value="West">西部</option></select>{tab!=='teams'&&!bpm&&<label className="min-games"><SlidersHorizontal size={14}/>最低场次<input type="number" min="0" max="82" value={minGP} onChange={e=>setMinGP(Math.min(82,Math.max(0,Number(e.target.value))))}/></label>}</div></div><div className="stats-table-wrap scroll-area">{filtered.length?<table className="data-table"><thead><tr><th className="rank-col">#</th><th className="name-col">{tab==='teams'?'TEAM':'PLAYER'}</th>{!bpm&&<th>GP</th>}{columns.map(m=><th key={m} className={chosenMetric===m?'sorted':''}><button onClick={()=>{if(chosenMetric===m)setDirection(-direction);else changeMetric(m)}} title={METRICS[m]?.description}>{METRICS[m]?.short}{chosenMetric===m&&<span>{direction===-1?'↓':'↑'}</span>}</button></th>)}</tr></thead><tbody>{filtered.slice((page-1)*25,page*25).map((r,i)=><tr key={r.PLAYER_ID||r.TEAM_ID}><td className="rank-col">{(page-1)*25+i+1}</td><td className="name-col"><div className="table-identity">{tab==='teams'?<StatTeamLogo row={r}/>:<Portrait id={r.PLAYER_ID} name={r.PLAYER_NAME}/>}<div><strong>{tab==='teams'?(Number(season.slice(0,4))<2024?r.TEAM_NAME:TEAMS[r.TEAM_ID]?.name||r.TEAM_NAME):<button className="player-text-link" onClick={()=>onPlayer(r.PLAYER_ID,season)}>{r.PLAYER_NAME}<ArrowUpRight size={11}/></button>}</strong><small>{tab==='teams'?r.TEAM_NAME:r.TEAM_ABBREVIATION}</small></div></div></td>{!bpm&&<td>{r.GP}</td>}{columns.map(m=><td key={m} className={chosenMetric===m?'highlight-stat':''}>{formatStat(r[m],m)}</td>)}</tr>)}</tbody></table>:<EmptyState title={bpm?'BPM 数据暂不可用':rows.length?'没有符合筛选条件的数据':'本赛季尚无常规赛统计'} icon={bpm?<WifiOff size={34} strokeWidth={1}/>:<Search size={34} strokeWidth={1}/>}><p>{bpm?'Basketball Reference 当前拒绝自动读取，恢复后会自动更新。':rows.length?'调整搜索内容或最低出场场次。':'当前赛季的常规赛统计尚未产生。'}</p>{!bpm&&!rows.length&&season==='2026-27'&&<button className="primary-button small" onClick={()=>{setSeason('2025-26');setMinGP(0)}}>查看 2025–26 完整赛季<ArrowRight size={14}/></button>}{bpm&&<a className="outline-button" href={data.url||`https://www.basketball-reference.com/leagues/NBA_${Number(season.slice(0,4))+1}_advanced.html`} target="_blank" rel="noreferrer">查看原始高阶数据<ArrowUpRight size={15}/></a>}{rows.length>0&&<button className="outline-button" onClick={()=>{setQ('');setMinGP(0);setConference('all')}}>重置筛选</button>}</EmptyState>}</div><footer className="page-footer"><span className="metric-definition"><Info size={13}/>{METRICS[chosenMetric]?.label}{bpm?' · 来源 Basketball Reference':' · NBA 官方场均数据'}</span><div className="pagination"><span>{filtered.length} {tab==='teams'?'支球队':'位球员'} · {page} / {Math.max(1,Math.ceil(filtered.length/25))}</span><button className="icon-button" aria-label="上一页" disabled={page<=1} onClick={()=>setPage(page-1)}><ChevronLeft size={16}/></button><button className="icon-button" aria-label="下一页" disabled={page*25>=filtered.length} onClick={()=>setPage(page+1)}><ChevronRight size={16}/></button></div></footer></>}</section>
}
function Standings({rows,loading,historical=false}:{rows:StatRow[];loading:boolean;historical?:boolean}){return <div className="standings-layout scroll-area">{['East','West'].map((conf,i)=><div className="conference-panel" key={conf}><div className="conference-header"><span className="conference-watermark">{conf==='East'?'E':'W'}</span><p>CONFERENCE {String(i+1).padStart(2,'0')}</p><h2>{conf==='East'?'EASTERN':'WESTERN'}<span>{conf==='East'?'东部联盟':'西部联盟'}</span></h2></div><table className="data-table standings-table"><thead><tr><th>#</th><th className="name-col">TEAM</th><th>W</th><th>L</th><th>WIN%</th><th>GB</th><th>L10</th><th>STRK</th></tr></thead><tbody>{rows.filter(r=>r.Conference===conf).sort((a,b)=>a.PlayoffRank-b.PlayoffRank).map((r,i)=><tr key={r.TeamID} className={cn(!historical&&i===5&&'playoff-line',!historical&&i===9&&'playin-line')}><td className={i<6?'playoff-rank':'rank-col'}>{i+1}</td><td className="name-col"><div className="table-identity"><StatTeamLogo row={r}/><div><strong>{historical&&r.TeamCity?r.TeamCity+' '+r.TeamName:TEAMS[r.TeamID]?.name||r.TeamName}</strong><small>{r.TeamAbbreviation||TEAMS[r.TeamID]?.code}</small></div></div></td><td className="highlight-stat">{r.WINS}</td><td>{r.LOSSES}</td><td>{(Number(r.WinPCT)*100).toFixed(1)}</td><td>{r.ConferenceGamesBack===0?'—':r.ConferenceGamesBack}</td><td>{r.L10??'—'}</td><td><span className={r.CurrentStreak>0?'winning':'losing'}>{r.strCurrentStreak??'—'}</span></td></tr>)}</tbody></table>{!rows.length&&<EmptyState title={loading?'正在获取联盟排名':'暂时无法获取排名'}/>}</div>)}{!historical&&<div className="standings-legend"><span><i className="legend-playoff"/>前 6 名 · 季后赛</span><span><i className="legend-playin"/>7—10 名 · 附加赛</span></div>}</div>}
function GameDetail({game,notebook,onUpdate,onBack,onWatch,saved,ready,predictions,refreshGame}:{game:Game;notebook:Notebook;onUpdate:(n:Observation)=>void;onBack:()=>void;onWatch:()=>void;saved:boolean;ready:boolean;predictions:PredictionStore;refreshGame:()=>Promise<Game>}){
 const season=gameSeason(game.gameId,defaultSeason);
 const box=useDataset('boxscore',season,game.gameId,15000);const roster=useDataset('roster',season);
 const [teamId,setTeamId]=useState(game.awayTeam.teamId);const [selected,setSelected]=useState(0);const [tab,setTab]=useState('auto');const [q,setQ]=useState('');const now=useGameClock();
 const official=box.data.game;const updated=official&&(official.gameStatus>game.gameStatus||official.gameStatus===game.gameStatus&&!box.data.stale)?{...game,...official,gameTimeUTC:game.gameTimeUTC} as Game:game;
 const phase=gamePhase(updated,now);const pregame=phase==='upcoming'||phase==='locked';const activeTab=tab==='auto'?(phase==='final'?'recap':'notes'):tab;
 const players:StatRow[]=useMemo(()=>official?[...(official.awayTeam?.players||[]).map((p:StatRow)=>({...p,teamId:game.awayTeam.teamId})),...(official.homeTeam?.players||[]).map((p:StatRow)=>({...p,teamId:game.homeTeam.teamId}))]:(roster.data.rows||[]).filter(p=>[game.homeTeam.teamId,game.awayTeam.teamId].includes(p.TEAM_ID)).map(p=>({personId:p.PERSON_ID,name:p.DISPLAY_FIRST_LAST,teamId:p.TEAM_ID,statistics:null})),[official,roster.data,game.homeTeam.teamId,game.awayTeam.teamId]);
 const visible=players.filter(p=>p.teamId===teamId&&p.name?.toLowerCase().includes(q.toLowerCase()));
 useEffect(()=>{if(visible.length&&!visible.some(p=>p.personId===selected))setSelected(visible[0].personId)},[visible,selected]);
 const player=players.find(p=>p.personId===selected);const fallbackNote=Object.values(notebook.observations).find(n=>n.gameId===game.gameId&&n.playerId===selected);
 const n=player?(notebook.observations[noteKey(game.gameId,selected)]||{gameId:game.gameId,playerId:selected,playerName:player.name,teamId:player.teamId,date:beijingDate(game.gameTimeUTC),matchup:`${game.awayTeam.teamTricode} @ ${game.homeTeam.teamTricode}`,ratings:{},focus:[],notes:'',moments:[],updatedAt:new Date().toISOString(),watched:false}):fallbackNote;
 const patch=(changes:Partial<Observation>)=>{if(n&&!pregame)onUpdate({...n,...changes,updatedAt:new Date().toISOString()})};
 const month=game.gameTimeUTC?beijingDate(game.gameTimeUTC).slice(0,7):'';const prediction=predictions.files[month]?.predictions.find(p=>p.gameId===game.gameId);
 useEffect(()=>{if(month)void predictions.reloadMonth(month,false)},[month,predictions.reloadMonth]);
 return <section className="page detail-page"><div className="detail-topline"><button className="back-button" onClick={onBack}><ArrowLeft size={15}/>比赛列表</button><span>{game.gameTimeUTC?dateLabel(beijingDate(game.gameTimeUTC))+' · '+clock(game.gameTimeUTC)+' CST':'开赛时间待定'}</span>{pregame?<AccountButton store={predictions}/>:<button className={cn('outline-button',notebook.watchedGames[game.gameId]&&'marked')} onClick={onWatch}>{notebook.watchedGames[game.gameId]?<CheckCheck size={15}/>:<Bookmark size={15}/>} {notebook.watchedGames[game.gameId]?'已观看':'标记已观看'}</button>}</div>
 <div className="detail-scoreboard" style={{'--away-color':TEAMS[game.awayTeam.teamId]?.color,'--home-color':TEAMS[game.homeTeam.teamId]?.color} as CSSProperties}><div className="detail-team away"><TeamLogo id={game.awayTeam.teamId}/><div><small>AWAY</small><h2>{game.awayTeam.teamTricode}</h2><p>{TEAMS[game.awayTeam.teamId]?.name}</p></div></div><div className="detail-score"><span className={cn('game-status',phase==='live'&&'is-live')}>{phase==='final'?'FINAL':phase==='live'?updated.gameStatusText:phase==='locked'?'LOCKED':'UPCOMING'}</span><strong>{pregame?<span className="vs">VS</span>:<>{updated.awayTeam.score}<i>:</i>{updated.homeTeam.score}</>}</strong><small>{game.arenaName||'NBA GAME'}</small></div><div className="detail-team home"><div><small>HOME</small><h2>{game.homeTeam.teamTricode}</h2><p>{TEAMS[game.homeTeam.teamId]?.name}</p></div><TeamLogo id={game.homeTeam.teamId}/></div></div>
 {pregame?<div className="pregame-stage scroll-area"><div className="pregame-intro"><p className="eyebrow">MAKE YOUR CALL</p><h2>这一场，<br/>你看好谁<span>？</span></h2><p>{phase==='locked'?'等待官方确认比赛状态':'只猜胜负，开赛前留下判断。'}</p></div>{game.gameTimeUTC?<PredictionTicket game={updated} store={predictions} refreshGame={refreshGame}/>:<EmptyState title="开赛时间待定"/>}</div>:<><div className="subnav detail-subnav">{phase==='final'&&<button className={cn(activeTab==='recap'&&'active')} onClick={()=>setTab('recap')}>赛后复盘</button>}<button className={cn(activeTab==='notes'&&'active')} onClick={()=>setTab('notes')}>观赛手记</button><button className={cn(activeTab==='box'&&'active')} onClick={()=>setTab('box')}>技术统计</button><div className="subnav-end">{prediction&&<PredictionBadge prediction={prediction} game={updated}/>} {activeTab==='notes'?<span className="save-status">{saved?<CheckCheck size={14}/>:<RefreshCw size={13}/>} {saved?'已保存在此浏览器':'保存中'}</span>:<Source data={box.data} loading={box.loading} onRefresh={box.reload}/>}</div></div>{activeTab==='box'?<BoxScore official={official}/>:<div className="observation-layout"><aside className="roster-panel"><div className="team-roster-switch">{[game.awayTeam,game.homeTeam].map(t=><button key={t.teamId} onClick={()=>{setTeamId(t.teamId);setQ('')}} className={cn(teamId===t.teamId&&'active')}><TeamLogo id={t.teamId}/>{t.teamTricode}</button>)}</div><label className="search-input"><Search size={14}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="找到你的观察对象" aria-label="搜索本场球员"/></label><div className="roster-list scroll-area">{visible.map(p=>{const note=notebook.observations[noteKey(game.gameId,p.personId)];return <button className={cn('roster-player',selected===p.personId&&'selected')} onClick={()=>setSelected(p.personId)} key={p.personId}><Portrait id={p.personId} name={p.name}/><div><strong>{p.name}</strong><small>{p.statistics&&p.played!=='0'?`${p.statistics.points} PTS · ${p.statistics.reboundsTotal} REB · ${p.statistics.assists} AST`:p.played==='0'?'DNP':TEAMS[p.teamId]?.code}</small></div>{note&&hasObservation(note)&&<i className="note-indicator"/>}</button>})}{!visible.length&&<p className="roster-empty">{box.loading||roster.loading?'正在读取球员名单…':'暂无匹配球员'}</p>}</div></aside><div className="observation-body scroll-area">{activeTab==='recap'?official?.gameStatus===3&&player?<><GamePostgame official={official}/><PlayerPostgame player={player} team={player.teamId===game.homeTeam.teamId?official.homeTeam:official.awayTeam} onObserve={()=>setTab('notes')}/></>:<EmptyState title="赛后技术统计尚未就绪"><p>NBA 官方发布后将显示球员总结。</p><button className="outline-button" onClick={box.reload}><RefreshCw size={14}/>刷新</button></EmptyState>:player&&n&&ready?<NoteEditor key={player.personId} player={player} note={n} onChange={patch}/>:<EmptyState title="选择一位球员，开始观察"><p>从左侧名单选择你的观察对象。</p></EmptyState>}</div></div>}</>}
 </section>
}
function NoteEditor({player,note,onChange}:{player:StatRow;note:Observation;onChange:(n:Partial<Observation>)=>void}){
 const [period,setPeriod]=useState('Q1');const [time,setTime]=useState('');const [moment,setMoment]=useState('');const [error,setError]=useState('');const stats=player.statistics;const addMoment=(e:React.FormEvent)=>{e.preventDefault();if(!/^([0-9]|1[0-2]):[0-5]\d$/.test(time.trim())){setError('请输入该节剩余时间，例如 8:32。');return}if(!moment.trim()){setError('请写下这次回合的观察。');return}if(note.moments.length>=200){setError('单位球员每场最多 200 条回合记录。');return}onChange({moments:[...note.moments,{id:crypto.randomUUID(),period,clock:time.trim(),text:moment.trim()}]});setMoment('');setError('')};
 return <div className="note-editor"><div className="observed-player"><div><p className="eyebrow">PLAYER OBSERVATION</p><h2>{player.name}</h2><p>{TEAMS[player.teamId]?.city} {TEAMS[player.teamId]?.name}{player.jerseyNum?' · #'+player.jerseyNum:''}{player.position?' · '+player.position:''}</p></div>{stats&&player.played!=='0'&&<div className="mini-box">{[['points','PTS'],['reboundsTotal','REB'],['assists','AST']].map(([k,l])=><span key={k}><b>{stats[k]??'—'}</b><small>{l}</small></span>)}</div>}</div><div className="section-label"><span>01</span><h3>今晚，重点看什么？</h3></div><div className="focus-chips">{DIMENSIONS.map(d=><button className={cn(note.focus.includes(d.key)&&'selected')} key={d.key} onClick={()=>onChange({focus:note.focus.includes(d.key)?note.focus.filter(x=>x!==d.key):[...note.focus,d.key]})}>{note.focus.includes(d.key)?<Check size={12}/>:<Plus size={12}/>} {d.name}</button>)}</div><div className="section-label"><span>02</span><h3>你的场上评价</h3><small>1–10 分 · 保留未评分</small></div><div className="ratings-grid">{DIMENSIONS.map(d=><div className="rating-item" key={d.key}><div><label htmlFor={'rating-'+d.key}>{d.name}</label><span className={note.ratings[d.key]?'rated':''}>{note.ratings[d.key]?<><b>{note.ratings[d.key]}</b><small>/10</small></>:'未评分'}</span></div><input id={'rating-'+d.key} type="range" min="0" max="10" step="1" value={note.ratings[d.key]||0} aria-valuetext={note.ratings[d.key]?note.ratings[d.key]+' 分':'未评分'} onChange={e=>{const ratings={...note.ratings};if(Number(e.target.value))ratings[d.key]=Number(e.target.value);else delete ratings[d.key];onChange({ratings})}} style={{'--range-value':(note.ratings[d.key]||0)*10+'%'} as CSSProperties}/><p>{d.hint}</p></div>)}</div><div className="section-label"><span>03</span><h3>观察与思考</h3></div><textarea className="observation-notes" aria-label="球员观察与思考" placeholder="他的防守站位有什么习惯？遇到挡拆怎么选择？三分是否依赖节奏？记下你真正看见的细节……" value={note.notes} maxLength={20000} onChange={e=>onChange({notes:e.target.value})}/><div className="section-label"><span>04</span><h3>记住这个回合</h3></div><form className="moment-form" onSubmit={addMoment}><div><select aria-label="节次" value={period} onChange={e=>setPeriod(e.target.value)}>{['Q1','Q2','Q3','Q4','OT','OT2','OT3'].map(p=><option key={p}>{p}</option>)}</select><input value={time} aria-label="该节剩余时间" placeholder="8:32" onChange={e=>setTime(e.target.value)} maxLength={5}/><input className="moment-text" value={moment} aria-label="回合观察" placeholder="这次协防，为什么晚了一步？" onChange={e=>setMoment(e.target.value)} maxLength={2000}/><button className="primary-button small" type="submit"><Plus size={16}/><span>记录</span></button></div>{error&&<p className="field-error" role="alert">{error}</p>}</form><div className="moments-list">{note.moments.map(m=><div key={m.id}><span className="moment-clock">{m.period}<b>{m.clock}</b></span><p>{m.text}</p><button className="icon-button" aria-label="删除这条回合观察" onClick={()=>onChange({moments:note.moments.filter(x=>x.id!==m.id)})}><X size={14}/></button></div>)}</div></div>
}
function BoxScore({official}:{official?:StatRow}){return <div className="boxscore-panels scroll-area">{official?[official.awayTeam,official.homeTeam].map(t=><section className="boxscore-panel" key={t.teamId}><div className="boxscore-heading"><TeamLogo id={t.teamId}/><h3>{t.teamCity} {t.teamName}</h3><strong>{t.score}</strong></div><div className="horizontal-scroll"><table className="data-table"><thead><tr><th className="name-col">PLAYER</th>{['MIN','PTS','REB','AST','STL','BLK','FG','3P','FT','TO','+/−'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{t.players.map((p:StatRow)=>{const s=p.statistics||{};return <tr key={p.personId}><td className="name-col"><div className="table-identity"><Portrait id={p.personId} name={p.name}/><strong>{p.name}</strong><small>{p.starter==='1'?'S':''}</small></div></td>{p.played==='0'?<td colSpan={11} className="dnp">DNP {p.notPlayingReason||''}</td>:<><td>{s.minutes?String(s.minutes).replace('PT','').replace('M',':').replace(/\.\d+S/,''):''}</td><td className="highlight-stat">{s.points}</td><td>{s.reboundsTotal}</td><td>{s.assists}</td><td>{s.steals}</td><td>{s.blocks}</td><td>{s.fieldGoalsMade}/{s.fieldGoalsAttempted}</td><td>{s.threePointersMade}/{s.threePointersAttempted}</td><td>{s.freeThrowsMade}/{s.freeThrowsAttempted}</td><td>{s.turnovers}</td><td className={s.plusMinusPoints>0?'winning':s.plusMinusPoints<0?'losing':''}>{s.plusMinusPoints>0?'+':''}{s.plusMinusPoints}</td></>}</tr>})}</tbody></table></div></section>):<EmptyState title="技术统计尚未发布"><p>开赛后自动读取 NBA 官方技术统计。</p></EmptyState>}</div>}
function Picker({rows,value,onChange,kind,label}:{rows:StatRow[];value:number;onChange:(n:number)=>void;kind:string;label:string}){
 const [open,setOpen]=useState(false);const [query,setQuery]=useState('');const ref=useRef<HTMLDivElement>(null);const key=kind==='players'?'PLAYER_ID':'TEAM_ID';const selected=rows.find(r=>r[key]===value);const options=rows.filter(r=>!query||`${r.PLAYER_NAME||r.TEAM_NAME} ${r.TEAM_ABBREVIATION||''} ${TEAMS[r.TEAM_ID]?.name||''}`.toLowerCase().includes(query.toLowerCase())).slice(0,40);
 useEffect(()=>{const close=(e:MouseEvent)=>{if(!ref.current?.contains(e.target as Node))setOpen(false)};document.addEventListener('mousedown',close);return()=>document.removeEventListener('mousedown',close)},[]);
 return <div className="entity-picker" ref={ref}><button className="picker-trigger" aria-label={label} aria-expanded={open} onClick={()=>{setOpen(!open);setQuery('')}}><span>{selected?selected.PLAYER_NAME||selected.TEAM_NAME:kind==='players'?'选择球员':'选择球队'}</span><ChevronDown size={17}/></button>{open&&<div className="picker-menu"><label className="search-input"><Search size={14}/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="输入名称搜索" aria-label={label+'搜索'} onKeyDown={e=>{if(e.key==='Escape')setOpen(false)}}/></label><div role="listbox" aria-label={label}>{options.map(r=><button role="option" aria-selected={value===r[key]} key={r[key]} onClick={()=>{onChange(r[key]);setOpen(false)}}>{kind==='players'?<Portrait id={r.PLAYER_ID} name={r.PLAYER_NAME}/>:<TeamLogo id={r.TEAM_ID}/>}<span>{r.PLAYER_NAME||r.TEAM_NAME}<small>{r.TEAM_ABBREVIATION||TEAMS[r.TEAM_ID]?.name}</small></span>{value===r[key]&&<Check size={15}/>}</button>)}{!options.length&&<p className="picker-empty">没有找到匹配项</p>}</div></div>}</div>
}
function Contrast({onToast,onPlayer}:{onToast:(s:string)=>void;onPlayer:(id:number,season?:string)=>void}){
 const [season,setSeason]=useState(defaultSeason);const [kind,setKind]=useState('players');const [a,setA]=useState(2544);const [b,setB]=useState(201939);const [group,setGroup]=useState('overview');const {data,loading,reload}=useDataset(kind,season);const rows=(data.rows||[]).filter(r=>Number(r.GP)>0);const idKey=kind==='players'?'PLAYER_ID':'TEAM_ID';const left=rows.find(r=>r[idKey]===a)||rows[0];const right=rows.find(r=>r[idKey]===b)||rows.find(r=>r[idKey]!==left?.[idKey]);
 const changeKind=(k:string)=>{setKind(k);setA(k==='players'?2544:1610612747);setB(k==='players'?201939:1610612744)};
 const metrics=group==='shooting'?['FG_PCT','FG3_PCT','FG3M','FT_PCT','TS_PCT','EFG_PCT']:group==='advanced'?['OFF_RATING','DEF_RATING','NET_RATING','USG_PCT','PACE','PIE']:['PTS','REB','AST','STL','BLK','TOV'];const common=kind==='teams'?metrics.filter(m=>m!=='USG_PCT'):metrics;
 return <section className="page contrast-page"><PageHeading eyebrow="CONTRAST" title="HEAD TO HEAD"><div className="segmented"><button className={kind==='players'?'active':''} onClick={()=>changeKind('players')}>球员对比</button><button className={kind==='teams'?'active':''} onClick={()=>changeKind('teams')}>球队对比</button></div><SeasonSelect value={season} onChange={setSeason}/></PageHeading>{left&&right?<><div className="comparison-cards"><EntityCard row={left} rows={rows} kind={kind} onChange={setA} side="left" onPlayer={id=>onPlayer(id,season)}/><div className="comparison-vs"><span>VS</span><button className="icon-button" aria-label="交换对比对象" onClick={()=>{setA(right[idKey]);setB(left[idKey])}}><MoveRight size={20}/><MoveRight size={20}/></button></div><EntityCard row={right} rows={rows} kind={kind} onChange={setB} side="right" onPlayer={id=>onPlayer(id,season)}/></div><div className="comparison-main scroll-area"><div className="comparison-bars"><div className="comparison-tabs">{[['overview','基础数据'],['shooting','投射效率'],['advanced','高阶表现']].map(([g,l])=><button key={g} onClick={()=>setGroup(g)} className={cn(group===g&&'active')}>{l}</button>)}</div><div className="comparison-metrics">{common.map(m=>{const av=left[m];const bv=right[m];const valid=av!==null&&bv!==null&&av!==undefined&&bv!==undefined;const max=Math.max(Math.abs(Number(av)||0),Math.abs(Number(bv)||0),.0001);const win=valid&&av!==bv?(METRICS[m]?.lower?(av<bv?'left':'right'):(av>bv?'left':'right')):'';return <div className="comparison-row" key={m}><span key={'a'+left[idKey]+m} className={cn('compare-value',win==='left'&&'winner')}>{formatStat(av,m)}</span><div className="bar-pair"><div className="bar-half left"><i style={{width:valid?Math.abs(av)/max*100+'%':'0'}}/></div><span title={METRICS[m]?.description}>{METRICS[m]?.short}<small>{METRICS[m]?.label}</small></span><div className="bar-half right"><i style={{width:valid?Math.abs(bv)/max*100+'%':'0'}}/></div></div><span key={'b'+right[idKey]+m} className={cn('compare-value',win==='right'&&'winner')}>{formatStat(bv,m)}</span></div>})}</div><div className="comparison-bar-footer"><span><i className="left-dot"/>{left.PLAYER_NAME||TEAMS[left.TEAM_ID]?.name}</span><span><i className="right-dot"/>{right.PLAYER_NAME||TEAMS[right.TEAM_ID]?.name}</span></div></div><div className="radar-panel"><div className="radar-heading"><h3>表现轮廓</h3><div className="radar-legend" aria-hidden="true"><i/><i/></div></div><Radar left={left} right={right} rows={rows} season={season}/></div></div></>:<EmptyState title="本赛季暂无可比较数据"><p>切换至已有常规赛统计的赛季。</p></EmptyState>}<footer className="page-footer"><Source data={data} loading={loading} onRefresh={reload}/></footer></section>
}
function EntityCard({row,rows,kind,onChange,side,onPlayer}:{row:StatRow;rows:StatRow[];kind:string;onChange:(id:number)=>void;side:string;onPlayer:(id:number)=>void}){return <div className={cn('entity-card',side)} style={{'--team-color':TEAMS[row.TEAM_ID]?.color||'#555'} as CSSProperties}><div className="entity-background-word">{row.TEAM_ABBREVIATION||TEAMS[row.TEAM_ID]?.code}</div><div className="entity-info"><span className="entity-team"><StatTeamLogo row={row}/>{kind==='teams'?row.TEAM_NAME:row.TEAM_ABBREVIATION||TEAMS[row.TEAM_ID]?.city}</span><Picker rows={rows} value={row[kind==='players'?'PLAYER_ID':'TEAM_ID']} onChange={onChange} kind={kind} label={side==='left'?'左侧对比对象':'右侧对比对象'}/><p>{kind==='players'?row.TEAM_ABBREVIATION:row.TEAM_NAME}<span>{row.GP} GP</span></p>{kind==='players'&&<button className="entity-profile-link" onClick={()=>onPlayer(row.PLAYER_ID)}>球员档案<ArrowUpRight size={12}/></button>}</div>{kind==='players'?<Portrait key={row.PLAYER_ID} id={row.PLAYER_ID} name={row.PLAYER_NAME}/>:<StatTeamLogo className="entity-large-logo" row={row}/>}</div>}
function Radar({left,right,rows,season}:{left:StatRow;right:StatRow;rows:StatRow[];season:string}){
 const axes=[{key:'PTS',label:'得分'},{key:'REB',label:'篮板'},{key:'AST',label:'助攻'},{key:'STL',label:'抢断'},{key:'BLK',label:'盖帽'},{key:'TS_PCT',label:'效率'}];
 const base=rows.filter(row=>Number(row.GP)>=(season===defaultSeason?1:20));
 if(base.length<3||axes.some(axis=>left[axis.key]==null||right[axis.key]==null))return <EmptyState title="样本不足"/>;
 const centerX=210,centerY=169,radius=113;
 const point=(index:number,r:number)=>[centerX+Math.cos(index*Math.PI/3-Math.PI/2)*r,centerY+Math.sin(index*Math.PI/3-Math.PI/2)*r];
 const grid=(scale:number)=>axes.map((_,i)=>point(i,radius*scale).join(',')).join(' ');
 const percentile=(row:StatRow,key:string)=>{const values=base.filter(value=>value[key]!=null);return values.filter(value=>Number(value[key])<=Number(row[key])).length/values.length};
 const polygon=(row:StatRow)=>axes.map((axis,i)=>point(i,Math.max(.025,percentile(row,axis.key))*radius).join(',')).join(' ');
 return <svg className="radar" viewBox="0 0 420 340" role="img" aria-label="数据对比"><circle className="radar-orbit" cx={centerX} cy={centerY} r={radius+17}/>{[.25,.5,.75,1].map(scale=><polygon key={scale} points={grid(scale)} className="radar-ring"/>)}{axes.map((axis,i)=>{const [x,y]=point(i,radius);const [tx,ty]=point(i,radius+37);return <g key={axis.key}><line x1={centerX} y1={centerY} x2={x} y2={y}/><circle className="radar-axis-dot" cx={x} cy={y} r="2"/><text x={tx} y={ty+4} textAnchor="middle">{axis.label}</text></g>})}<g className="radar-series" key={(left.PLAYER_ID||left.TEAM_ID)+':'+(right.PLAYER_ID||right.TEAM_ID)}><polygon points={polygon(left)} pathLength="1" className="radar-a"/><polygon points={polygon(right)} pathLength="1" className="radar-b"/>{[left,right].map((row,j)=>axes.map((axis,i)=>{const [x,y]=point(i,Math.max(.025,percentile(row,axis.key))*radius);return <circle key={j+axis.key} cx={x} cy={y} r="4" className={j?'radar-dot-b':'radar-dot-a'}><title>{(row.PLAYER_NAME||row.TEAM_NAME)+' · '+axis.label+' '+formatStat(row[axis.key],axis.key)}</title></circle>}))}</g></svg>;
}
function NotebookDialog({notebook,onClose,onOpen,onExport,onImport,onDelete}:{notebook:Notebook;onClose:()=>void;onOpen:(id:string)=>void;onExport:()=>void;onImport:(file:File)=>void;onDelete:(key:string)=>void}){
 const dialog=useRef<HTMLDialogElement>(null);const file=useRef<HTMLInputElement>(null);const [q,setQ]=useState('');const [deleting,setDeleting]=useState('');useEffect(()=>{dialog.current?.showModal();return()=>dialog.current?.close()},[]);const notes=Object.values(notebook.observations).filter(hasObservation).filter(n=>!q||`${n.playerName} ${n.matchup} ${n.notes} ${n.moments.map(m=>m.text).join(' ')}`.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt));const rated=Object.values(notebook.observations).filter(n=>Object.keys(n.ratings).length).length;return <dialog ref={dialog} className="notebook-dialog" onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>{if(e.target===e.currentTarget)onClose()}} aria-labelledby="notebook-title"><div className="notebook-content"><div className="notebook-heading"><div><p className="eyebrow">MY COURTSIDE</p><h2 id="notebook-title">THE FIELD NOTES<span>.</span></h2></div><button className="icon-button" onClick={onClose} aria-label="关闭观赛手记"><X size={23}/></button></div><div className="notebook-summary"><span><b>{Object.values(notebook.watchedGames).filter(Boolean).length}</b>场已观看</span><span><b>{Object.values(notebook.observations).filter(hasObservation).length}</b>条球员观察</span><span><b>{rated}</b>位已评分</span></div><div className="notebook-toolbar"><label className="search-input"><Search size={15}/><input aria-label="搜索观赛手记" placeholder="球员、比赛或笔记内容" value={q} onChange={e=>setQ(e.target.value)}/></label><button className="outline-button" onClick={()=>file.current?.click()}><Upload size={14}/>导入</button><button className="outline-button" onClick={onExport}><Download size={14}/>导出</button><input ref={file} hidden type="file" accept="application/json,.json" onChange={e=>{if(e.target.files?.[0])onImport(e.target.files[0]);e.target.value=''}}/></div><div className="notebook-list scroll-area">{notes.length?notes.map(n=>{const key=noteKey(n.gameId,n.playerId);const ratings=Object.values(n.ratings);return <article key={key} className="notebook-entry"><div className="notebook-entry-top"><Portrait id={n.playerId} name={n.playerName}/><div><h3>{n.playerName}</h3><span>{n.matchup} · {n.date}</span></div>{ratings.length>0&&<div className="note-score"><b>{(ratings.reduce((a,b)=>a+b,0)/ratings.length).toFixed(1)}</b><span>个人评分均值</span></div>}</div>{n.notes&&<p className="note-excerpt">{n.notes}</p>}<div className="notebook-entry-bottom"><span>{n.moments.length} 条回合记录 · {n.focus.length} 项观察重点</span><div>{deleting===key?<><button className="danger-button" onClick={()=>{onDelete(key);setDeleting('')}}>确认删除</button><button className="text-button" onClick={()=>setDeleting('')}>取消</button></>:<button className="icon-button" aria-label={'删除 '+n.playerName+' 的这条记录'} onClick={()=>setDeleting(key)}><Trash2 size={14}/></button>}<button className="text-button" onClick={()=>onOpen(n.gameId)}>继续观察<ArrowUpRight size={14}/></button></div></div></article>}):<EmptyState title={q?'没有找到匹配的手记':'你的下一次观赛，从这里开始'} icon={<BookOpen size={36} strokeWidth={1}/>}><p>{q?'换一个球员名或关键词。':'进入一场比赛，选择球员并写下第一条观察。'}</p></EmptyState>}</div><footer className="notebook-footer"><span><CheckCircle2 size={13}/>自动保存在当前浏览器</span><span>导出可备份或转移到其他设备</span></footer></div></dialog>}
